/**
 * The exact sentence Vigil says, unprompted, when live metrics confirm the fix.
 * Spoken through Agora's speak API rather than generated by the LLM: a "think" update that
 * arrives while Vigil is mid-turn can be queued and never spoken, and this moment is the proof
 * that the fix worked, so it must always be heard.
 */
export function recoveryAnnouncement(engineer: string, metricLabel: string, value: string, baseline: string): string {
  const label = /^[A-Z]{2}/.test(metricLabel) ? metricLabel : metricLabel.charAt(0).toLowerCase() + metricLabel.slice(1);
  const verb = /[^s]s$/i.test(metricLabel) ? 'are' : 'is'; // "errors" are, "success" is
  return `${engineer}, good news: ${label} ${verb} back to ${spoken(value)}, near the ${spoken(baseline)} baseline. Live metrics confirm the fix. Shall I update the status page and post in the incident channel?`;
}

/** "1.0%" reads as "1 percent"; "0.4%" as "0.4 percent". */
function spoken(value: string): string {
  return value.replace(/\.0(?=%)/, '').replace(/%$/, ' percent');
}
